using Microsoft.AspNetCore.Components;
using sv_69d6f5da432242a88a389c2b5bae8444.Services;

namespace sv_69d6f5da432242a88a389c2b5bae8444.Components.Pages;

public partial class Settings : ComponentBase
{
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string toastMessage = string.Empty;
    private string toastType = string.Empty;

    // Profile state
    private string profileDisplayName = string.Empty;
    private string profileEmail = string.Empty;
    private string profileAvatarUrl = string.Empty;
    private string profileBio = string.Empty;
    private UserProfile? savedProfile;

    // Notifications state
    private bool notifEmail;
    private bool notifPush;
    private bool notifWeeklyDigest;
    private List<string> mutedChannels = new();
    private List<string> availableChannels = new()
    {
        "general", "announcements", "engineering", "design", "marketing", "random"
    };

    // Security state
    private SecuritySettings? securitySettings;
    private bool twoFactorEnabled;
    private bool showPasswordPanel;
    private string currentPassword = string.Empty;
    private string newPassword = string.Empty;
    private string confirmPassword = string.Empty;
    private string currentSessionId = string.Empty;
    private bool showRevokeConfirmation;
    private string revokeSessionId = string.Empty;
    private string revokeDeviceName = string.Empty;

    // Appearance state
    private string appearanceTheme = "System";
    private string appearanceFontSize = "Medium";
    private string appearanceLanguage = "en";
    private bool appearanceCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadSection(activeSection);
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        isLoading = true;
        await LoadSection(section);
    }

    private async Task LoadSection(string section)
    {
        try
        {
            switch (section)
            {
                case "Profile":
                    var profile = await SettingsService.GetProfileAsync();
                    savedProfile = profile;
                    profileDisplayName = profile.DisplayName;
                    profileEmail = profile.Email;
                    profileAvatarUrl = profile.AvatarUrl;
                    profileBio = profile.Bio;
                    break;

                case "Notifications":
                    var prefs = await SettingsService.GetNotificationPrefsAsync();
                    notifEmail = prefs.EmailNotifications;
                    notifPush = prefs.PushNotifications;
                    notifWeeklyDigest = prefs.WeeklyDigest;
                    mutedChannels = new List<string>(prefs.MutedChannels);
                    break;

                case "Security":
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    twoFactorEnabled = securitySettings.TwoFactorEnabled;
                    // Assume first session is current
                    currentSessionId = securitySettings.Sessions.FirstOrDefault()?.Id ?? string.Empty;
                    break;

                case "Appearance":
                    var appearance = await SettingsService.GetAppearanceAsync();
                    appearanceTheme = appearance.Theme;
                    appearanceFontSize = appearance.FontSize;
                    appearanceLanguage = appearance.Language;
                    appearanceCompactMode = appearance.CompactMode;
                    break;
            }
        }
        catch (Exception ex)
        {
            ShowToast($"Error loading settings: {ex.Message}", "toast-error");
        }
        finally
        {
            isLoading = false;
        }
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = new UserProfile(profileDisplayName, profileEmail, profileAvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "toast-success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            profileDisplayName = savedProfile.DisplayName;
            profileEmail = savedProfile.Email;
            profileAvatarUrl = savedProfile.AvatarUrl;
            profileBio = savedProfile.Bio;
        }
        ShowToast("Changes discarded.", "toast-info");
    }

    // Notifications methods
    private bool IsChannelMuted(string channel) => mutedChannels.Contains(channel);

    private void ToggleChannelMute(string channel, bool muted)
    {
        if (muted && !mutedChannels.Contains(channel))
        {
            mutedChannels.Add(channel);
        }
        else if (!muted)
        {
            mutedChannels.Remove(channel);
        }
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(notifEmail, notifPush, notifWeeklyDigest, new List<string>(mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "toast-success");
    }

    // Security methods
    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "toast-error");
            return;
        }

        if (newPassword != confirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "toast-error");
            return;
        }

        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = string.Empty;
        newPassword = string.Empty;
        confirmPassword = string.Empty;
        showPasswordPanel = false;
        ShowToast("Password updated successfully!", "toast-success");
    }

    private void ConfirmRevokeSession(string sessionId, string deviceName)
    {
        revokeSessionId = sessionId;
        revokeDeviceName = deviceName;
        showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        await SettingsService.RevokeSessionAsync(revokeSessionId);
        showRevokeConfirmation = false;
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Session revoked.", "toast-success");
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        revokeSessionId = string.Empty;
        revokeDeviceName = string.Empty;
    }

    // Appearance methods
    private string GetPreviewFontSize() => appearanceFontSize switch
    {
        "Small" => "12px",
        "Large" => "18px",
        _ => "14px"
    };

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(appearanceTheme, appearanceFontSize, appearanceLanguage, appearanceCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "toast-success");
    }

    // Toast methods
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(4000);
        toastMessage = string.Empty;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast()
    {
        toastMessage = string.Empty;
    }
}

.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    color: #555;
    font-weight: 500;
    transition: all 0.2s ease;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #e9ecef;
    color: #333;
}

.settings-sidebar li.active {
    background: #e3f2fd;
    color: #1976d2;
    border-left-color: #1976d2;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Main content */
.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
    position: relative;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
    border-bottom: 2px solid #e0e0e0;
    padding-bottom: 0.5rem;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
    font-size: 1.1rem;
    color: #555;
}

/* Form controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.15);
}

/* Buttons */
.button-group {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

.btn-primary {
    background: #1976d2;
    color: #fff;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover {
    background: #1565c0;
}

.btn-secondary {
    background: #fff;
    color: #555;
    border: 1px solid #ccc;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-secondary:hover {
    background: #f5f5f5;
    border-color: #999;
}

.btn-danger {
    background: #d32f2f;
    color: #fff;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
}

.btn-danger:hover {
    background: #c62828;
}

.btn-small {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e0e0e0;
}

.avatar-url {
    font-size: 0.85rem;
    color: #777;
    word-break: break-all;
}

/* Toggle switches */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
    color: #444;
}

.toggle-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1976d2;
}

/* Channel list */
.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.75rem;
    background: #f8f9fa;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
}

.channel-item:hover {
    background: #e9ecef;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 1.25rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
    color: #333;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 0.8rem;
    color: #777;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e0e0e0;
}

/* Security status */
.security-toggle {
    margin: 1.5rem 0;
}

.status-indicator {
    margin-left: 0.5rem;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
}

.status-enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-disabled {
    background: #fce4ec;
    color: #c62828;
}

.info-text {
    font-size: 0.85rem;
    color: #777;
    margin: 0.5rem 0;
}

.current-badge {
    font-size: 0.8rem;
    padding: 0.2rem 0.6rem;
    background: #e3f2fd;
    color: #1976d2;
    border-radius: 12px;
    font-weight: 500;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.5rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem 1rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #555;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.sessions-table td {
    font-size: 0.9rem;
    color: #444;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-group label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-weight: normal;
}

.radio-group input[type="radio"] {
    accent-color: #1976d2;
}

/* Appearance preview */
.appearance-preview {
    padding: 1.5rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin: 1rem 0;
    transition: all 0.3s ease;
}

.preview-light {
    background: #ffffff;
    color: #333;
}

.preview-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-compact {
    padding: 0.75rem;
    line-height: 1.2;
}

.preview-header {
    font-weight: 600;
    margin-bottom: 0.5rem;
    font-size: 1.1em;
}

.preview-text {
    margin-bottom: 0.75rem;
    opacity: 0.85;
}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 4px;
    border: none;
    cursor: pointer;
    font-size: 0.85em;
}

.preview-light .preview-button {
    background: #1976d2;
    color: #fff;
}

.preview-dark .preview-button {
    background: #64b5f6;
    color: #1e1e1e;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    padding: 2rem;
    border-radius: 12px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.modal-dialog h3 {
    margin-top: 0;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    padding: 0.85rem 1.25rem;
    border-radius: 8px;
    font-size: 0.9rem;
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 1rem;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
    z-index: 2000;
    animation: slideIn 0.3s ease;
}

.toast-success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast-error {
    background: #fce4ec;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

.toast-info {
    background: #e3f2fd;
    color: #1565c0;
    border: 1px solid #90caf9;
}

.toast-close {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    opacity: 0.7;
    color: inherit;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes slideIn {
    from {
        transform: translateY(1rem);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

/* Loading */
.loading-spinner {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3rem;
